"""A fictional, non-diagnostic learning scenario with bilingual feedback."""
STAGES = (
    {"id": "investigate", "title": {"en": "Find the cause", "zu": "Thola imbangela"}, "story": {"en": "A neighbourhood has lost its water supply. What would you investigate first?", "zu": "Umphakathi awusenawo amanzi. Yini ongayihlola kuqala?"}, "choices": [
        {"id": "pipes", "title": {"en": "Check pipes and pumps", "zu": "Hlola amapayipi namaphampu"}, "feedback": {"en": "You gathered technical evidence. This can help locate a fault, but residents' immediate needs still matter.", "zu": "Uqoqe ubufakazi bezobuchwepheshe. Lokhu kungasiza ukuthola inkinga, kodwa izidingo zezakhamuzi zisabalulekile."}, "career_id": "engineering"},
        {"id": "people", "title": {"en": "Ask which homes are affected", "zu": "Buza ukuthi yimiphi imizi ethintekile"}, "feedback": {"en": "You gathered community evidence. This helps identify urgent needs, but the cause of the failure still needs investigation.", "zu": "Uqoqe ulwazi lomphakathi. Lokhu kusiza ukuthola izidingo eziphuthumayo, kodwa imbangela yenkinga isadinga ukuhlolwa."}, "career_id": "community"},
        {"id": "supply", "title": {"en": "Count the available water tanks", "zu": "Bala amathangi amanzi akhona"}, "feedback": {"en": "You checked available resources. This supports planning while others investigate the interruption.", "zu": "Uhlolile izinsiza ezikhona. Lokhu kusiza ekuhleleni ngesikhathi kusaphenywa ukuphazamiseka."}, "career_id": "logistics"}]},
    {"id": "prioritize", "title": {"en": "Choose a first action", "zu": "Khetha isinyathelo sokuqala"}, "story": {"en": "The repair may take a day. Some households have no stored water. What is your first response?", "zu": "Ukulungisa kungathatha usuku. Eminye imizi ayinawo amanzi agciniwe. Yini ongayenza kuqala?"}, "choices": [
        {"id": "repair", "title": {"en": "Coordinate the repair team", "zu": "Hlela ithimba lokulungisa"}, "feedback": {"en": "Repair work addresses the source of the problem. Emergency access to water also needs a plan.", "zu": "Ukulungisa kubhekana nembangela yenkinga. Kudingeka nohlelo lwamanzi oluphuthumayo."}, "career_id": "engineering"},
        {"id": "needs", "title": {"en": "Identify households needing urgent support", "zu": "Thola imizi edinga usizo oluphuthumayo"}, "feedback": {"en": "You considered immediate needs. Planning must also account for available supply and repair time.", "zu": "Ucabange ngezidingo eziphuthumayo. Ukuhlela kufanele kubheke namanzi akhona nesikhathi sokulungisa."}, "career_id": "community"},
        {"id": "deliver", "title": {"en": "Plan temporary water delivery", "zu": "Hlela ukulethwa kwamanzi kwesikhashana"}, "feedback": {"en": "A delivery plan can reduce disruption. You would still need to check fairness, safety and available quantities.", "zu": "Uhlelo lokuletha amanzi lunganciphisa ukuphazamiseka. Kusadingeka uhlole ukulingana, ukuphepha nobuningi bamanzi."}, "career_id": "logistics"}]},
    {"id": "review", "title": {"en": "Review your solution", "zu": "Buyekeza isixazululo sakho"}, "story": {"en": "Water is flowing again. How would you learn from what happened?", "zu": "Amanzi aseyatholakala futhi. Ungafunda kanjani kulokho okwenzekile?"}, "choices": [
        {"id": "prevent", "title": {"en": "Check how to prevent another failure", "zu": "Hlola indlela yokuvimbela enye inkinga"}, "feedback": {"en": "Prevention can reduce future failures. Maintenance and technical analysis are worth exploring.", "zu": "Ukuvimbela kunganciphisa izinkinga ezizayo. Ungahlola ukulungisa nokuhlaziya kwezobuchwepheshe."}, "career_id": "engineering"},
        {"id": "listen", "title": {"en": "Ask residents what worked", "zu": "Buza izakhamuzi ukuthi yini esebenzile"}, "feedback": {"en": "Feedback reveals experiences that numbers alone may miss. Research and community services use this approach.", "zu": "Imibono yabantu iveza izinto izinombolo ezingase zingazivezi. Ucwaningo nezinsiza zomphakathi kusebenzisa le ndlela."}, "career_id": "community"},
        {"id": "plan", "title": {"en": "Improve the emergency delivery plan", "zu": "Thuthukisa uhlelo lokuletha amanzi oluphuthumayo"}, "feedback": {"en": "Reviewing a plan can improve coordination next time. Logistics and operations use similar thinking.", "zu": "Ukubuyekeza uhlelo kungathuthukisa ukuxhumana ngokuzayo. Ezokuthutha nokusebenza kusebenzisa ukucabanga okufanayo."}, "career_id": "logistics"}]},
)

def evaluate_stage(stage_id: str, choice_id: str) -> dict:
    stage = next((s for s in STAGES if s["id"] == stage_id), None)
    choice = next((c for c in stage["choices"] if c["id"] == choice_id), None) if stage else None
    if choice is None:
        raise ValueError("Unknown stage or choice")
    return {"stage_id": stage_id, "choice_id": choice_id, "feedback": choice["feedback"], "explore_career_id": choice["career_id"], "note": "One decision does not measure ability or determine a career."}
